import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:provider/provider.dart';

import 'app/app.dart';
import 'core/services/storage_service.dart';
import 'data/providers/audio_provider.dart';
import 'data/providers/collaboration_provider.dart';
import 'data/providers/mindmap_provider.dart';
import 'data/providers/theme_provider.dart';

// Optional: generated by the FlutterFire CLI (`flutterfire configure`).
// When it exists it is preferred, because it also covers iOS / web / desktop.
// See docs/SETUP_FIREBASE.md — the import below is commented out on purpose so
// the project compiles before that file has been generated.
// import 'firebase_options.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  await SystemChrome.setPreferredOrientations([
    DeviceOrientation.portraitUp,
    DeviceOrientation.landscapeLeft,
    DeviceOrientation.landscapeRight,
  ]);

  SystemChrome.setSystemUIOverlayStyle(
    const SystemUiOverlayStyle(
      statusBarColor: Colors.transparent,
      statusBarIconBrightness: Brightness.dark,
    ),
  );

  // Local settings first: they must work even without a network/backend.
  await StorageService.init();

  // Firebase is required by the cloud features (auth, mindmap sync). If the
  // platform config is missing we keep the app alive so the UI can be
  // developed/inspected, and log exactly what is missing.
  final bool firebaseReady = await _initFirebase();

  runApp(
    MultiProvider(
      providers: [
        ChangeNotifierProvider(create: (_) => ThemeProvider()),
        ChangeNotifierProvider(create: (_) => MindmapProvider()),
        ChangeNotifierProvider(create: (_) => AudioProvider()),
        ChangeNotifierProvider(create: (_) => CollaborationProvider()),
        Provider<bool>.value(value: firebaseReady),
      ],
      child: const VipMindApp(),
    ),
  );
}

/// Returns `true` when Firebase was initialised successfully.
Future<bool> _initFirebase() async {
  try {
    // Once `lib/firebase_options.dart` has been generated, switch to:
    //   await Firebase.initializeApp(
    //     options: DefaultFirebaseOptions.currentPlatform,
    //   );
    await Firebase.initializeApp();
    return true;
  } catch (error) {
    debugPrint('[VipMind] Firebase.initializeApp() failed: $error');
    debugPrint(
      '[VipMind] Cloud features (login, sync) are disabled for this run.\n'
      '  Android needs: android/app/google-services.json + the '
      '"com.google.gms.google-services" Gradle plugin (both are in the repo).\n'
      '  iOS needs: ios/Runner/GoogleService-Info.plist (NOT in the repo yet).\n'
      '  Best fix: run `flutterfire configure` — see docs/SETUP_FIREBASE.md.',
    );
    return false;
  }
}
